#include <iostream>
#include <vector>
#include <string>
using namespace std;

int main() {
    string s;
    cin >> s;

    string stack;
    bool ok = true;
    for (char ch : s) {
        if (ch == '(' || ch == '[' || ch == '{') {
            stack += ch;
        } else {
            char open = ch == ')' ? '(' : (ch == ']' ? '[' : '{');
            if (stack.empty() || stack.back() != open) {
                ok = false;
                break;
            }
            stack.pop_back();
        }
    }
    cout << (ok && stack.empty() ? "yes" : "no") << "\n";

    return 0;
}

code.java:
import java.util.*;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        String s = sc.next();

        Deque<Character> stack = new ArrayDeque<>();
        boolean ok = true;
        for (int i = 0; i < s.length(); i++) {
            char ch = s.charAt(i);
            if (ch == '(' || ch == '[' || ch == '{') {
                stack.push(ch);
            } else {
                char open = ch == ')' ? '(' : (ch == ']' ? '[' : '{');
                if (stack.isEmpty() || stack.peek() != open) {
                    ok = false;
                    break;
                }
                stack.pop();
            }
        }
        System.out.println(ok && stack.isEmpty() ? "yes" : "no");
    }
}
